mapper.update:
update JCMS_USER set
	UPD_ID = #{updId}
	,UPD_DT = SYSDATE()
	 ,INSTITUTION_ID = #{institutionId} 
	 ,USER_PWD = #{userPwd} 
	 ,USER_NM = #{userNm} 
	 ,GENDER = #{gender} 
	 ,BIRTH = #{birth} 
	 ,MOBILE = #{mobile} 
	 ,ADDR = #{addr} 
	 , EMAIL = #{email} 
	 , USER_ST = #{userSt} 
	 , USER_OUT_RSN = #{userOutRsn} 
where
	USER_ID = #{userId}

