					where 1=1
					
						AND ROLE_AUTH IN
						
							#{value}
						
					
	) as TR
	join (select * from JCMS_USER
	               where DEL_ID is null
					 and USER_ID LIKE #{userId} 
					 and INSTITUTION_ID = #{institutionId} 
					 and USER_LOGIN_ID LIKE CONCAT('%', #{userLoginIdLike}, '%') 
					 and USER_NM LIKE CONCAT('%', #{userNmLike}, '%') 
					 and USER_ST = #{userSt} 
   	) as TU
	on TU.USER_ID = TR.USER_ID
	order by ${sort} ${sortOrd}
	
		limit #{start}, #{length}

        select COUNT(1)
